const presets={homepage:"把下面内容改写成网站首页可直接使用的文案。要求：中文、克制、不要 AI 腔、不要空话、尽量短。",module:"把下面内容整理成适合网站模块页的结构。输出：标题、简短引言、3个小模块，每个模块 1 句话。",notes:"把下面内容整理成工作笔记。要求：更像真实记录，不要营销感，不要大而空。",refine:"把下面内容润色得更自然、更简洁，保留原意，不要夸张。"},form=document.querySelector("#studio-form"),presetButtons=document.querySelectorAll("[data-preset]"),instructionInput=document.querySelector("#instruction"),contentInput=document.querySelector("#content"),modeInput=document.querySelector("#mode"),resultBox=document.querySelector("#result"),statusText=document.querySelector("#status-text"),statusDot=document.querySelector("#status-dot"),copyButton=document.querySelector("#copy-output");function setStatus(t,e){statusDot.className="status-dot",t&&statusDot.classList.add(t),statusText.textContent=e}async function checkHealth(){try{const t=await fetch("/api/ai/health",{headers:{Accept:"application/json"}}),e=await t.json();if(t.ok&&e.configured)return void setStatus("ok",`已连接，默认模型：${e.model}`);setStatus("warn","工作台已上线，但服务器还没配置 OpenAI API Key。")}catch(t){setStatus("warn","无法连接到内容工作台后端。")}}presetButtons.forEach(t=>{t.addEventListener("click",()=>{const e=t.dataset.preset;instructionInput.value=presets[e]||""})}),copyButton.addEventListener("click",async()=>{const t=resultBox.textContent.trim();t&&"输出会显示在这里。"!==t&&(await navigator.clipboard.writeText(t),copyButton.textContent="已复制",setTimeout(()=>{copyButton.textContent="复制结果"},1500))}),form.addEventListener("submit",async t=>{t.preventDefault();const e=contentInput.value.trim(),o=instructionInput.value.trim(),n=modeInput.value;if(e){resultBox.textContent="正在生成...",setStatus("","处理中...");try{const t=await fetch("/api/ai/process",{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({mode:n,instruction:o,content:e})}),s=await t.json();if(!t.ok)return resultBox.textContent=s.error||"请求失败。",void setStatus("warn","生成失败。");resultBox.textContent=s.output||"没有返回内容。",setStatus("ok",`已完成，模型：${s.model}`)}catch(t){resultBox.textContent="请求失败，请检查网络或后端服务。",setStatus("warn","无法调用工作台。")}}else setStatus("warn","先输入要处理的内容。")}),checkHealth();